import re
t=open("03_kich-ban-chinh-sua.md",encoding="utf-8").read()
L=t.split("\n")
heads=[(i,l) for i,l in enumerate(L) if l.startswith("#### Cụm ")]
print("clusters",len(heads))
prev=0; bad=[]
def sec(s):
    m,ss=s.split(":");return int(m)*60+int(ss)
for i,(ln,h) in enumerate(heads):
    m=re.match(r"#### Cụm (\d{3}) · (\d+:\d\d)–(\d+:\d\d) · ",h)
    n=int(m.group(1)); a=sec(m.group(2)); b=sec(m.group(3))
    if n!=prev+1 or a!=(n-1)*30 or b!=n*30: bad.append(h[:60])
    prev=n
print("bad seq",bad)
# per-cluster checks
for idx,(ln,h) in enumerate(heads):
    end=heads[idx+1][0] if idx+1<len(heads) else len(L)
    blk=L[ln:end]
    s="\n".join(blk)
    for key in ["**Nhân vật:**","**Chức năng:**","**Khung kết:**","**Móc"]:
        if key not in s: print("missing",key,h[:30])
    # dialogue followed by VN
    for j,l in enumerate(blk):
        if re.match(r'- \*\*[A-ZĐ][A-Z .ĐÁÀẢÃẠÂẤẦẨẪẬĂẮẰẲẴẶÉÈẺẼẸÊẾỀỂỄỆÍÌỈĨỊÓÒỎÕỌÔỐỒỔỖỘƠỚỜỞỠỢÚÙỦŨỤƯỨỪỬỮỰÝỲỶỸỴ]+\*\*.*: "',l):
            if j+1>=len(blk) or not blk[j+1].strip().startswith("*(VN)"):
                print("noVN",h[:30],l[:70])
    nd=sum(1 for l in blk if re.match(r'- \*\*[^*]+\*\*[^"]*: "',l))
    if nd>10: print("many lines",nd,h[:40])
print("edit notes",t.count("> ✎ **Sửa ở bản 03"))
print("tap headings",len([l for l in L if l.startswith("### TẬP")]))
PY

