import re
t=open("03_kich-ban-chinh-sua.md",encoding="utf-8").read()
L=t.split("\n")
pat=re.compile(r'^- \*\*[^*]+\*\*.*"')
n=bad=0; mx=(0,"")
heads=[(i,l) for i,l in enumerate(L) if l.startswith("#### Cụm ")]
for idx,(ln,h) in enumerate(heads):
    end=heads[idx+1][0] if idx+1<len(heads) else len(L)
    blk=L[ln:end]; c=0
    for j,l in enumerate(blk):
        if pat.match(l) and not l.startswith("- **Jordyn tát") and not l.startswith("- **Regina tát"):
            n+=1; c+=1
            if not blk[j+1].strip().startswith("*(VN)"):
                bad+=1; print("noVN",h[:28],"|",l[:80])
    if idx>=72 and c>mx[0]: mx=(c,h[:40])
print("dialogue lines",n,"bad",bad,"max lines in a P2 cluster",mx)
PY

