    return $null
}

function Update-CongCuNgoai {
    $script:GitExe = Find-CongCuNgoai 'git.exe' -DuPhong @(
        "$env:ProgramFiles\Git\cmd\git.exe", "$env:LOCALAPPDATA\Programs\Git\cmd\git.exe")
    $script:GhExe = Find-CongCuNgoai 'gh.exe' -DuPhong @(
        "$env:ProgramFiles\GitHub CLI\gh.exe", "$env:LOCALAPPDATA\Programs\GitHub CLI\gh.exe")
    $script:OpenSslExe = Find-CongCuNgoai 'openssl.exe' -UuTien @(
        "$env:ProgramFiles\Git\mingw64\bin\openssl.exe", "$env:LOCALAPPDATA\Programs\Git\mingw64\bin\openssl.exe")
    $script:CurlExe = Find-CongCuNgoai 'curl.exe' -UuTien @("$env:WINDIR\System32\curl.exe")
    $script:SshKeygenExe = Find-CongCuNgoai 'ssh-keygen.exe' -UuTien @("$env:WINDIR\System32\OpenSSH\ssh-keygen.exe") -DuPhong @(
        "$env:ProgramFiles\Git\usr\bin\ssh-keygen.exe")
    $pythonDuPhong = @(Get-ChildItem "$env:LOCALAPPDATA\Programs\Python\Python3*\python.exe" -ErrorAction SilentlyContinue |
        Sort-Object FullName -Descending | ForEach-Object { $_.FullName })
    $script:PythonExe = Find-CongCuNgoai 'python.exe' -DuPhong $pythonDuPhong
function Connect-GitHub([string]$Goc, $Cfg) {
    # Tạo repo RIÊNG TƯ trên GitHub cho dự án (hỏi trước). Trả về $true nếu đã có remote origin.
    if ((Invoke-Git $Goc remote get-url origin).Ma -eq 0) { return $true }
    if (-not (Test-DaDangNhapGitHub)) {
        Write-Canh 'Chưa đăng nhập GitHub. Chạy 1-CAI-DAT-LAN-DAU.bat rồi bấm LUU.bat, máy sẽ hỏi lại.'
        return $false
    }
    if (-not (Read-CoKhong "Tạo repo RIÊNG TƯ '$($Cfg.thuMuc)' trên GitHub và đẩy dự án lên?" $true)) { return $false }
    $r = Invoke-Native $script:GhExe @('repo', 'create', $Cfg.thuMuc, '--private', '--source', $Goc, '--remote', 'origin',
        '--description', "Kho bằng chứng sáng tạo: $($Cfg.ten)")
    if ($r.Ma -ne 0) { Write-Canh "Không tạo được repo: $($r.Text)"; return $false }
    Write-Ok "Đã tạo repo riêng tư: $((Invoke-Git $Goc remote get-url origin).Text)"
    $true
}

# ----------------------------------------------------------------------------
#  Hiển thị kết quả
# ----------------------------------------------------------------------------
function Show-DanhSachThayDoi($Khac, [int]$ToiDa = 15) {
    $dong = @()
    foreach ($x in $Khac.Them) { $dong += "  + $x  (mới)" }
    foreach ($x in $Khac.Sua)  { $dong += "  ~ $x  (sửa)" }
    foreach ($x in $Khac.Xoa)  { $dong += "  - $x  (xóa)" }
    foreach ($d in ($dong | Select-Object -First $ToiDa)) { Write-Host "     $d" -ForegroundColor Gray }
    if ($dong.Count -gt $ToiDa) { Write-Tin "... và $($dong.Count - $ToiDa) file khác" }
}

function Show-KetQuaLuu($Kq) {
    Write-Host ''
    if ($Kq.HoiThoai -gt 0) { Write-Ok "Đã chép $($Kq.HoiThoai) hội thoại Claude Code vào 08_hoi-thoai-ai/claude-code/" }
    if ($Kq.GhiNhatKy) { Write-Ok 'Đã ghi vào nhật ký sáng tạo (07_nhat-ky-sang-tao.md)' }
    if ($Kq.Manifest) {
        Write-Ok "Đã lập mã SHA-256 cho $($Kq.SoTep) file -> $($Kq.Manifest)"
        switch ($Kq.Dau.Ots) {
            'ok'    { Write-Ok 'OpenTimestamps: đã gửi lên Bitcoin (vài giờ sau mới xác nhận xong, máy tự cập nhật)' }
            'loi'   { Write-Canh 'OpenTimestamps: chưa gửi được (mất mạng?). Lần lưu sau sẽ có dấu mới.' }
            default { Write-Canh 'OpenTimestamps: chưa cài (chạy 1-CAI-DAT-LAN-DAU.bat)' }
        }
        switch ($Kq.Dau.Tsa) {
            'ok'    { Write-Ok ('FreeTSA (RFC 3161): ' + (Format-Gio $Kq.Dau.GioTsa 'dd/MM/yyyy HH:mm:ss')) }
            'loi'   { Write-Canh 'FreeTSA: chưa lấy được dấu thời gian (mất mạng?)' }
            default { Write-Canh 'FreeTSA: thiếu OpenSSL hoặc curl' }
